res_scene = primitives.call(name="observe_vima_scene", include_raw=True, view="top")
res_i5 = primitives.call(name="inspect_vima_instance", segmentation_id=5, view="top")
res_i6 = primitives.call(name="inspect_vima_instance", segmentation_id=6, view="top")
res_bp = primitives.call(
    name="build_vima_pick_place_action", source_segmentation_id=5, target_segmentation_id=6, view="top"
)

if res_scene.ok:
    print("Scene keys:", list(res_scene.output.keys()))
    for k in res_scene.output:
        if k != "raw_observation":
            print(k, ":", res_scene.output[k])
        else:
            print("raw_observation keys:", list(res_scene.output["raw_observation"].keys()))
if res_i5.ok:
    print("Instance 5:", res_i5.output)
if res_i6.ok:
    print("Instance 6:", res_i6.output)
if res_bp.ok:
    print("Build pick place 5->6:", res_bp.output)

raw = res_scene.output["raw_observation"]
print("raw_observation keys:", list(raw.keys()))
for k, v in raw.items():
    if isinstance(v, dict):
        print(k, "dict keys:", list(v.keys()))
    else:
        print(k, type(v))

res_p2 = primitives.call(name="observe_vima_prompt", query="scene", prompt="scene")
print("res_p2 prompt_assets:", res_p2.output.get("prompt_assets"))

print("res_scene.output keys:", list(res_scene.output.keys()))
for k, v in res_scene.output.items():
    if isinstance(v, dict):
        print(" ", k, "keys:", list(v.keys()))
    else:
        print(" ", k, "type:", type(v))

# Check if we can inspect prompt instances or pass prompt='{scene}'
r1 = primitives.call(name="inspect_vima_instances", prompt="{scene}", query="scene", view="top")
print("r1 keys:", list(r1.output.keys()))
print("r1 exact_prompt_bindings:", r1.output.get("exact_prompt_bindings"))

